    const root=node('section','life-atlas');q.root=root;
    const tools=node('div','la-tools'),tabs=node('div','la-tabs');
    q.buttons={};
    for(const [mode,title] of [['territory','当年版图'],['focus','当年近景'],['country','全国']]){
      const b=node('button','',title);b.type='button';b.onclick=()=>{q.mode=mode;paint(q)};q.buttons[mode]=b;tabs.append(b);
    }
    q.trailButton=node('button','la-trail','历年行迹');q.trailButton.type='button';q.trailButton.onclick=()=>{q.trail=!q.trail;paint(q)};
    tools.append(tabs,q.trailButton);
    q.plate=node('div','la-plate');q.meta=node('span','la-meta');q.plot=s('svg',{role:'img'});q.plate.append(q.plot,q.meta);
    q.legend=node('div','la-legend');q.inspect=node('p','la-place');q.inspect.setAttribute('aria-live','polite');
    q.counts=node('p','la-counts');
    q.summary=node('div','la-summary');q.more=node('details','la-more');
    q.more.append(node('summary','','据点、史料与底图'));q.moreDetails=node('div');q.more.append(q.moreDetails);
    root.append(tools,q.plate,q.legend,q.counts,q.inspect,q.summary,q.more);container.replaceChildren(root);
    q.observer=new ResizeObserver(()=>{if(!root.isConnected){q.observer.disconnect();return;}if(q.year&&Math.abs(root.clientWidth-q.w)>1)paint(q)});q.observer.observe(root);
