    const major=new Set(['nj','hz','wc','kf','bj','cd','km','dl','gz','fz','sz','py','nc','cz']);
    const labelOrder=[...markers].sort((a,b)=>Number(b.priority)-Number(a.priority)||Number(major.has(b.k))-Number(major.has(a.k))||Number(changed.has(b.k))-Number(changed.has(a.k)));
